UPDATE ref_producers SET lat=COALESCE(lat,(SELECT g.lat FROM _coe_geo g JOIN ref_coffees c ON c.url=g.url WHERE c.producer_id=ref_producers.id LIMIT 1)), lng=COALESCE(lng,(SELECT g.lng FROM _coe_geo g JOIN ref_coffees c ON c.url=g.url WHERE c.producer_id=ref_producers.id LIMIT 1)) WHERE id IN (SELECT c.producer_id FROM _coe_geo g JOIN ref_coffees c ON c.url=g.url);
DROP TABLE _coe_geo;
